// FirstEnabledTransition is Appendix D selectTransitions, the half only this
// document can answer: the first of state's own transitions, in document order,
// that event enables and whose guard holds. The engine walks the atomic states
// and their ancestors and keeps the ordered set; the null event asks for
// eventless transitions.
//line signed_tester.scxml:5
func (p *SignedTesterPolicy) FirstEnabledTransition(state SignedTesterState, event SignedTesterEvent, engine *sce.Engine[SignedTesterState, SignedTesterEvent]) (sce.EnabledTransition[SignedTesterState, sce.HistoryID], bool) {
	switch state {
	case SignedTesterStateExchanging:
		if event == SignedTesterEventSceTestSnapshot {
			// docs/SCE_TEST_PROFILE.md §12.3: a branch of the test component,
			// guarded by its cond and then its match on the round's snapshot.
			if scetestprofile.Receives(p.sceTestContext, "sut", "signed.reading", func(sceMessage sce_signed_reading_within.Value) bool { return sce_signed_reading_within.Matches(sceMessage) }) {
				return sce.EnabledTransition[SignedTesterState, sce.HistoryID]{
					Source:          state,
					Targets:         transitionTargetsOfSignedTester[state][0],
					TransitionIndex: 0,
					HasActions:      true,
					IsInternal:      false,
				}, true
			}
		}
		if event == SignedTesterEventSceTestSnapshot {
			// docs/SCE_TEST_PROFILE.md §12.3: a branch of the test component,
			// guarded by its cond and then its match on the round's snapshot.
			if p.sceTestContext.TimedOut("deadline") {
				return sce.EnabledTransition[SignedTesterState, sce.HistoryID]{
					Source:          state,
					Targets:         transitionTargetsOfSignedTester[state][1],
					TransitionIndex: 1,
					HasActions:      true,
					IsInternal:      false,
				}, true
			}
		}
	}
	return sce.EnabledTransition[SignedTesterState, sce.HistoryID]{}, false
}

// TakeTransition takes a branch of the test component before the microstep
// exits any state (docs/SCE_TEST_PROFILE.md §4.4, P4 step 1, §12.3): it removes
// what the branch matched from the round's snapshot, writes its record in the
// test log, and holds a message its content reads in the payload field of its
// record's event (`Transition::native_take`). The policy is a sce.TransitionTaker.
func (p *SignedTesterPolicy) TakeTransition(source SignedTesterState, transitionIndex int, engine *sce.Engine[SignedTesterState, SignedTesterEvent]) {
	switch source {
	case SignedTesterStateExchanging:
		switch transitionIndex {
		case 0:
			p.sceTestContext.Receive("sut")
		case 1:
			p.sceTestContext.Timeout("deadline")
		}
	}
}

